from functools import lru_cache

# Model parameters
PD = {'S1': 0.02, 'S2': 0.05, 'S3': 0.12, 'S4': 0.30, 'S5': 0.60, 'S6': 0.90}
EV = {s: (1-p)*1000 - p*16000 for s, p in PD.items()}
segments = ['S1','S2','S3','S4','S5','S6']

likelihood = {
    'S1': {'bureau': [0.06,0,0.08,0.02,0.26,0.58], 'income': [0,0,0.04,0.08,0.54,0.34], 'bank': [0.06,0.02,0.06,0.16,0.46,0.24]},
    'S2': {'bureau': [0.06,0,0.02,0.04,0.40,0.48], 'income': [0,0.06,0.12,0.50,0.22,0.10], 'bank': [0.10,0,0.08,0.38,0.32,0.12]},
    'S3': {'bureau': [0.02,0.06,0.08,0.28,0.44,0.12], 'income': [0.04,0.28,0.48,0.12,0.08,0], 'bank': [0.06,0.16,0.40,0.22,0.08,0.08]},
    'S4': {'bureau': [0.02,0.04,0.06,0.24,0.42,0.22], 'income': [0.18,0.40,0.32,0.08,0.02,0], 'bank': [0.10,0.08,0.42,0.30,0.06,0.04]},
    'S5': {'bureau': [0.08,0.06,0.16,0.42,0.16,0.12], 'income': [0.22,0.40,0.30,0.06,0,0.02], 'bank': [0.14,0.42,0.24,0.14,0.02,0.04]},
    'S6': {'bureau': [0.04,0.10,0.48,0.18,0.14,0.06], 'income': [0.14,0.38,0.34,0.10,0.02,0.02], 'bank': [0.18,0.52,0.26,0.02,0,0.02]},
}

checks = ['bureau', 'income', 'bank']
CHECK_COST = 20
MAX_CHECKS = 8

def expected_value(prior):
    return sum(prior[s]*EV[s] for s in segments)

def bayesian_update(prior, check, band):
    post = {}
    total = 0
    for s in segments:
        post[s] = prior[s] * likelihood[s][check][band]
        total += post[s]
    for s in segments:
        post[s] /= total
    return post

# Convert prior to tuple for hashing
def prior_to_tuple(prior):
    return tuple(round(prior[s], 10) for s in segments)

# We'll use a simpler approach: compute optimal action with limited depth
# Since the state space is continuous, we'll compute on-demand with memoization

from functools import lru_cache

@lru_cache(maxsize=None)
def optimal_value(prior_tuple, checks_remaining):
    prior = {s: prior_tuple[i] for i, s in enumerate(segments)}
    ev_approve = expected_value(prior)
    ev_decline = 0

    best = max(ev_approve, ev_decline)

    if checks_remaining > 0:
        for check in checks:
            marg = [0]*6
            for b in range(6):
                for s in segments:
                    marg[b] += prior[s] * likelihood[s][check][b]

            exp_value = 0
            for b in range(6):
                if marg[b] > 1e-10:
                    post = bayesian_update(prior, check, b)
                    post_tuple = prior_to_tuple(post)
                    exp_value += marg[b] * optimal_value(post_tuple, checks_remaining - 1)

            net_value = exp_value - CHECK_COST
            if net_value > best:
                best = net_value

    return best

@lru_cache(maxsize=None)
def optimal_action(prior_tuple, checks_remaining):
    prior = {s: prior_tuple[i] for i, s in enumerate(segments)}
    ev_approve = expected_value(prior)
    ev_decline = 0

    best_val = max(ev_approve, ev_decline)
    best_act = 'approve' if ev_approve >= ev_decline else 'decline'

    if checks_remaining > 0:
        for check in checks:
            marg = [0]*6
            for b in range(6):
                for s in segments:
                    marg[b] += prior[s] * likelihood[s][check][b]

            exp_value = 0
            for b in range(6):
                if marg[b] > 1e-10:
                    post = bayesian_update(prior, check, b)
                    post_tuple = prior_to_tuple(post)
                    exp_value += marg[b] * optimal_value(post_tuple, checks_remaining - 1)

            net_value = exp_value - CHECK_COST
            if net_value > best_val + 1e-6:
                best_val = net_value
                best_act = ('check', check)

    return best_act, best_val

# Test on applicant 1 first
